#[test]
fn nested_retirement_projection_obeys_original_source_depth_and_json_oracle(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/♻️retirement.json")).unwrap();let value=|name:&str|ValueError::new(ValueRefusalKind::Canceled,fixture[name].as_str().unwrap().to_owned());let inner=semio_framework_value::OriginalRetirementFailure::from_causes(Some(value("innerPrimary")),Some(value("innerWork")),Some(value("innerReceipt"))).with_retained_progress(RetainedCloneProgress{copied_bytes:7,..Default::default()});let(storage,_)=semio_framework_value::OriginalFailureStorage::admit(semio_framework_value::OriginalFailureStorage::birth_bytes()).result.unwrap();let original=storage.attach_owned_parts(inner,None,Some(value("outerWork")),None).with_retained_progress(RetainedCloneProgress{copied_bytes:11,..Default::default()});
 for row in fixture["sourceDepthCases"].as_array().unwrap(){let depth=row["depth"].as_u64().unwrap()as usize;let accepted=row["accepted"].as_bool().unwrap();assert_eq!(accepted,depth>=fixture["nodes"].as_u64().unwrap()as usize);let mut observer=|_|true;let mut allocations=0usize;let mut allocate=|_:semio_framework_value::native_encoding::NativeEncodeAllocationEvent|{allocations+=1;Ok(())};let mut action=|_:usize,_:usize|Ok(());let mut allocation_loan_issuer=semio_framework_value::native_encoding::NativeEncodeAllocationIssuer::new();let mut allocation_loan=allocation_loan_issuer.scoped_loan(&mut allocate);let mut control=semio_framework_value::NativeEncodeControl::new_scoped_source(65536,depth,&mut observer,&mut allocation_loan,&mut action);let error=super::codec::retirement_value(&original,&mut control).unwrap_err();assert_eq!(error.kind,if accepted{ValueRefusalKind::UnsupportedOwner}else{ValueRefusalKind::DepthLimit});drop(control);drop(allocation_loan);drop(allocate);if !accepted{assert_eq!(allocations,0)}}
 for row in fixture["enclosingDepthCases"].as_array().unwrap(){let depth=row["depth"].as_u64().unwrap()as usize;let accepted=row["accepted"].as_bool().unwrap();assert_eq!(accepted,depth>=fixture["nodes"].as_u64().unwrap()as usize+1);let mut observer=|_|true;let mut allocate=|_:semio_framework_value::native_encoding::NativeEncodeAllocationEvent|Ok(());let mut action=|_:usize,_:usize|Ok(());let mut allocation_loan_issuer=semio_framework_value::native_encoding::NativeEncodeAllocationIssuer::new();let mut allocation_loan=allocation_loan_issuer.scoped_loan(&mut allocate);let mut control=semio_framework_value::NativeEncodeControl::new_scoped_source(65536,depth,&mut observer,&mut allocation_loan,&mut action);let error=control.scoped_depth(usize::MAX,|control|super::codec::retirement_value(&original,control)).unwrap_err();assert_eq!(error.kind,if accepted{ValueRefusalKind::UnsupportedOwner}else{ValueRefusalKind::DepthLimit});}
 let mut observer=|_|true;let mut control=semio_framework_value::NativeEncodeControl::new(65536,&mut observer);let projected=super::codec::retirement_value(&original,&mut control).unwrap();let json=serde_json::to_value(&projected).unwrap();assert_eq!(json["progressOverride"]["copiedBytes"],11);assert_eq!(json["child"]["progressOverride"]["copiedBytes"],7);assert_eq!(json["workRefusal"]["message"],fixture["outerWork"]);assert_eq!(json["child"]["primary"]["message"],fixture["innerPrimary"]);assert_eq!(json["child"]["workRefusal"]["message"],fixture["innerWork"]);assert_eq!(json["child"]["receiptRefusal"]["message"],fixture["innerReceipt"]);drop(control);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};close(projected,grant,4096);close(original,grant,4096);
}

#[test]
fn receiving_wire_retains_each_allocation_cause_and_physical_progress(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🛂️receiving-allocation.json")).unwrap();let names=fixture["channels"].as_array().unwrap();let owned=|i:usize|ValueError::new(ValueRefusalKind::Canceled,names[i].as_str().unwrap().to_owned());let grant=semio_framework_value::RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096};for actual in fixture["actualCapacityCases"].as_array().unwrap(){let mut receiving=OriginalReceivingPrimary{retirement_failure:None,work_refusal:None,primary:None,quote_refusal:None,allocation_refusal:None,allocation_failure:Some(Default::default()),native_allocation:Some(semio_framework_value_native_owned::native_decoding::NativeDecodeAllocationOutcome{request:None,admitted:true,quote_refusal:Some(owned(3)),primary:Some(owned(0)),extent_refusal:Some(owned(1)),settlement_refusal:Some(owned(2)),actual:Some(0)}),receipt_refusal:Some(ValueError::new(ValueRefusalKind::Canceled,fixture["receipt"].as_str().unwrap().to_owned())),progress:Default::default()};let allocation=receiving.allocation_failure.as_mut().unwrap();allocation.primary=Some(owned(0));allocation.admission=Some(owned(1));allocation.forwarded_admission=Some(owned(2));allocation.scoped_admission=Some(owned(3));allocation.forwarded_quote=Some(owned(4));allocation.scoped_quote=Some(owned(5));allocation.forwarded_post=Some(owned(6));allocation.scoped_post=Some(owned(7));allocation.forwarded_cancel=Some(owned(8));allocation.scoped_cancel=Some(owned(9));allocation.receipt=Some(owned(10));allocation.extent=Some(owned(11));allocation.progress.prior_admitted_bytes=(!actual.is_null()).then(||fixture["priorAdmittedBytes"].as_u64().unwrap()as usize);allocation.progress.requested_bytes=(!actual.is_null()).then(||fixture["requestedBytes"].as_u64().unwrap()as usize);allocation.progress.maximum_bytes=(!actual.is_null()).then(||fixture["maximumBytes"].as_u64().unwrap()as usize);allocation.progress.admitted_bytes=fixture["admittedBytes"].as_u64().unwrap()as usize;allocation.progress.actual_capacity_bytes=actual.as_u64().map(|v|v as usize);let original=NativeSnapshotFailure::from(receiving);assert_eq!(original.receipt_refusal().unwrap().message.as_ref(),fixture["receipt"].as_str().unwrap());let mut observe=|_|true;let mut encoder=semio_framework_value::NativeEncodeControl::new(grant.maximum_capacity_bytes,&mut observe);let wire=original.to_value_controlled(&mut encoder).unwrap();drop(encoder);let json=serde_json::to_value(&wire).unwrap();for name in names{let name=name.as_str().unwrap();assert_eq!(json["cause"]["allocationFailure"][name]["message"],name)}assert_eq!(json["cause"]["allocationFailure"]["progress"]["actualCapacityBytes"],*actual);let decoded=receive_wire(&wire);assert_eq!(decoded,original);close(decoded,grant,100000);close(wire,grant,100000);close(original,grant,100000);}}

#[test]
fn incomplete_allocation_request_refuses_encoding_without_moving_its_owner(){let mut receiving=OriginalReceivingPrimary{retirement_failure:None,work_refusal:None,primary:None,quote_refusal:None,allocation_refusal:None,allocation_failure:Some(Default::default()),native_allocation:None,receipt_refusal:None,progress:Default::default()};receiving.allocation_failure.as_mut().unwrap().progress.requested_bytes=Some(73);let failure=NativeSnapshotFailure::from(receiving);let mut observer=|_|true;let mut encoder=semio_framework_value::NativeEncodeControl::new(65536,&mut observer);assert!(failure.to_value_controlled(&mut encoder).is_err());assert_eq!(failure.receiving_primary().unwrap().allocation_failure.as_ref().unwrap().progress.requested_bytes,Some(73));drop(encoder);close(failure,semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:128},4096);}

#[test]fn encode_effect_failure_retains_every_original_cause_and_projects_wire(){use semio_framework_value::native_encoding::{NativeEncodeAllocation,NativeEncodeAllocationOutcome,NativeEncodeEffectFailure};let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️encode-effect.json")).unwrap();let source=&fixture["encodeEffect"];let error=|v:&serde_json::Value|Some(ValueError::new(ValueRefusalKind::Canceled,v["message"].as_str().unwrap().to_owned()));let a=&source["allocation"];let request=&a["request"];let effect=NativeEncodeEffectFailure{primary:error(&source["primary"]),invariant:error(&source["invariant"]),physical_invariant:error(&source["physicalInvariant"]),capacity_invariant:error(&source["capacityInvariant"]),work:error(&source["work"]),local:error(&source["local"]),physical:error(&source["physical"]),allocation:Some(NativeEncodeAllocationOutcome{request:Some(NativeEncodeAllocation{bytes:request["bytes"].as_u64().unwrap()as usize,owned_bytes:request["ownedBytes"].as_u64().unwrap()as usize,next_owned_bytes:request["nextOwnedBytes"].as_u64().unwrap()as usize,maximum_bytes:request["maximumBytes"].as_u64().unwrap()as usize}),admitted:a["admitted"].as_bool().unwrap(),primary:error(&a["primary"]),forwarded_quote:error(&a["forwardedQuote"]),scoped_quote:error(&a["scopedQuote"]),extent_refusal:error(&a["extentRefusal"]),forwarded_refusal:error(&a["forwardedRefusal"]),scoped_refusal:error(&a["scopedRefusal"]),actual:a["actual"].as_u64().map(|v|v as usize)})};let pointers=[effect.primary.as_ref().unwrap().message.as_ptr(),effect.invariant.as_ref().unwrap().message.as_ptr(),effect.physical_invariant.as_ref().unwrap().message.as_ptr(),effect.capacity_invariant.as_ref().unwrap().message.as_ptr(),effect.work.as_ref().unwrap().message.as_ptr(),effect.local.as_ref().unwrap().message.as_ptr(),effect.physical.as_ref().unwrap().message.as_ptr(),effect.allocation.as_ref().unwrap().scoped_refusal.as_ref().unwrap().message.as_ptr()];let failure=NativeSnapshotFailure::from_encode_effect(effect,RetainedCloneProgress::default());let effect=failure.encode_effect().unwrap();assert_eq!([effect.primary.as_ref().unwrap().message.as_ptr(),effect.invariant.as_ref().unwrap().message.as_ptr(),effect.physical_invariant.as_ref().unwrap().message.as_ptr(),effect.capacity_invariant.as_ref().unwrap().message.as_ptr(),effect.work.as_ref().unwrap().message.as_ptr(),effect.local.as_ref().unwrap().message.as_ptr(),effect.physical.as_ref().unwrap().message.as_ptr(),effect.allocation.as_ref().unwrap().scoped_refusal.as_ref().unwrap().message.as_ptr()],pointers);let mut observe=|_|true;let mut native=semio_framework_value::NativeEncodeControl::new(1<<20,&mut observe);let wire=failure.to_value_controlled(&mut native).unwrap();assert_eq!(serde_json::to_value(&wire).unwrap(),fixture);drop(native);let grant=semio_framework_value::RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096};close(wire,grant,100000);close(failure,grant,100000);}
